//
// ⚠️ PROVENANCE OF THE POPULATION. Remote Cloudflare D1 `luminous`
// (`database_id 735f0fb5-cdc3-494d-8b97-74a8ade0124a`) over MCP on **2026-08-09**:
//
//   SELECT id, name, legal_standard, stage, evolve_from, hp, attacks_json
